/** Public data/API schema. Increment on an incompatible contract change. */
export const SCHEMA_VERSION = 1;

/** Clamp x to the closed interval [lo, hi]. */
export function clamp(x, lo, hi) {
  return x < lo ? lo : x > hi ? hi : x;
}

/** Clamp x to the closed interval [0, 1]. */
export function clamp01(x) {
  return clamp(x, 0, 1);
}

/** Clamp x symmetrically to [-|a|, |a|]. */
export function clampSym(x, a) {
  const magnitude = Math.abs(a);
  return clamp(x, -magnitude, magnitude);
}

/** Linear interpolation. t is deliberately not clamped, so this also extrapolates. */
export function lerp(a, b, t) {
  return a + (b - a) * t;
}

/** Round x to a decimal digit position (negative positions are allowed). */
export function round(x, digits) {
  const factor = 10 ** digits;
  return Math.round(x * factor) / factor;
}

/** The suite's canonical mulberry32 stream. */
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * The most common existing rngFrom variant: a golden-ratio-scrambled LCG.
 * Numeric seeds only; its historical / 0xffffffff normalization is preserved.
 */
export function rngFrom(seed) {
  let state = (seed * 2654435761) >>> 0;
  return () => ((state = (state * 1664525 + 1013904223) >>> 0) / 0xffffffff);
}

/** Median of a non-empty numeric array, without mutating the input. */
export function median(arr) {
  if (arr.length === 0) {
    throw new RangeError('median requires at least one value');
  }
  if (arr.some(Number.isNaN)) return NaN;
  const sorted = [...arr].sort((a, b) => a - b);
  const middle = sorted.length >> 1;
  return sorted.length % 2
    ? sorted[middle]
    : (sorted[middle - 1] + sorted[middle]) / 2;
}

function defaultClock() {
  return globalThis.performance.now();
}

/**
 * Warm fn, measure one call per round, then select the requested statistic.
 * `stat` has intentionally no default. `clock` exists for deterministic tests.
 */
export function bench(fn, { warmup = 0, rounds, stat, clock = defaultClock } = {}) {
  if (typeof fn !== 'function') throw new TypeError('bench fn must be a function');
  if (!Number.isInteger(warmup) || warmup < 0) {
    throw new RangeError('bench warmup must be a non-negative integer');
  }
  if (!Number.isInteger(rounds) || rounds < 1) {
    throw new RangeError('bench rounds must be a positive integer');
  }
  if (stat !== 'min' && stat !== 'median') {
    throw new TypeError("bench stat must be 'min' or 'median'");
  }
  if (typeof clock !== 'function') throw new TypeError('bench clock must be a function');

  for (let i = 0; i < warmup; i += 1) fn(i);

  const samples = [];
  for (let i = 0; i < rounds; i += 1) {
    const start = clock();
    fn(i);
    samples.push(clock() - start);
  }

  const value = stat === 'min' ? Math.min(...samples) : median(samples);
  return { stat, value, samples };
}
